Step_Timer(IN := TRUE, PT := Step_Duration[Step_Index]);
IF Step_Timer.Q THEN
    Step_Timer(IN := FALSE);
    Step_Index := Step_Index + 1;
    IF Step_Index > MAX_STEP THEN
        Step_Index := 0;
        Sequence_Complete := TRUE;
    END_IF;
END_IF;

(* Output assignment based on step *)
CASE Step_Index OF
  0: Output_A := TRUE; Output_B := FALSE;
  1: Output_A := FALSE; Output_B := TRUE;
  ELSE: Output_A := FALSE; Output_B := FALSE;
END_CASE;
